{
 "requirements": [
  {
   "id": "R1",
   "text": "Server accepts at least 10 concurrent clients."
  },
  {
   "id": "R2",
   "text": "Clients register a unique username; duplicates are rejected."
  },
  {
   "id": "R3",
   "text": "Messages are broadcast to all other clients with the sender's username."
  },
  {
   "id": "R4",
   "text": "Private messages via /msg <user> <text>."
  },
  {
   "id": "R5",
   "text": "All clients are notified when a user joins or leaves."
  },
  {
   "id": "R6",
   "text": "/who lists online users."
  }
 ],
 "constraints": [
  "Python 3 standard library only",
  "Default port 5050, configurable"
 ],
 "deliverables": [
  "server.py and client.py (zip)",
  "README",
  "2-page concurrency report (PDF)",
  "demo video"
 ]
}

